import os
import tomllib
from typing import Any, Optional


class ConfigError(Exception):
    def __init__(self, message: str):
        super().__init__(message)


def _coerce(value: str, target_type: type) -> Any:
    if target_type is int:
        return int(value)
    if target_type is float:
        return float(value)
    if target_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ValueError(f"invalid boolean: {value}")
    if target_type is str:
        return value
    raise ValueError(f"unknown type: {target_type}")


def _get_leaf(d: dict, path: list) -> tuple[Any, dict]:
    cur = d
    for k in path[:-1]:
        cur = cur[k]
    return cur[path[-1]], cur


def load(
    defaults: dict,
    toml_path: Optional[str] = None,
    prefix: str = "APP",
    env: Optional[dict] = None,
) -> dict:
    result = dict(defaults)
    if toml_path:
        try:
            with open(toml_path, "rb") as f:
                toml = tomllib.load(f)
            for k, v in toml.items():
                result[k] = v
        except FileNotFoundError:
            pass
    if env is None:
        env = dict(os.environ)
    for name, value in env.items():
        if not name.startswith(f"{prefix}__"):
            continue
        path = name[len(prefix) + 2:].split("__")
        try:
            leaf, parent = _get_leaf(result, path)
            expected = type(leaf)
            coerced = _coerce(value, expected)
            result[path[-1]] = coerced
        except (KeyError, ValueError):
            raise ConfigError(
                f"{name}: no default for this key" if "no default" in str(value) else f"invalid value for {name}: expected {expected.__name__}, got \"{value}\""
            )
    return result

import os
import tempfile
import pytest
from envcfg import load, ConfigError


def test_defaults_only():
    cfg = load({"a": 1, "b": 2})
    assert cfg == {"a": 1, "b": 2}


def test_toml_overrides_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'a = 10\nb = 20')
        tmp = f.name
    try:
        cfg = load({"a": 1, "b": 2}, toml_path=tmp)
        assert cfg == {"a": 10, "b": 20}
    finally:
        os.unlink(tmp)


def test_missing_toml_file_skipped():
    cfg = load({"a": 1}, toml_path="/nonexistent.toml")
    assert cfg == {"a": 1}


def test_nested_defaults():
    cfg = load({"server": {"port": 8080}})
    assert cfg == {"server": {"port": 8080}}


def test_toml_nested_overrides_defaults():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'[server]\nport = 9000')
        tmp = f.name
    try:
        cfg = load({"server": {"port": 8080}}, toml_path=tmp)
        assert cfg == {"server": {"port": 9000}}
    finally:
        os.unlink(tmp)


def test_env_overrides_defaults():
    cfg = load({"a": 1}, prefix="APP", env={"APP__A": "42"})
    assert cfg == {"a": 42}


def test_env_overrides_toml():
    with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
        f.write(b'a = 10')
        tmp = f.name
    try:
        cfg = load({}, toml_path=tmp, prefix="APP", env={"APP__A": "100"})
        assert cfg == {"a": 100}
    finally:
        os.unlink(tmp)


def test_int_coercion():
    cfg = load({"a": 1}, prefix="APP", env={"APP__A": "42"})
    assert cfg == {"a": 42}


def test_float_coercion():
    cfg = load({"a": 1.0}, prefix="APP", env={"APP__A": "3.14"})
    assert cfg == {"a": 3.14}


def test_bool_coercion():
    cfg = load({"a": False}, prefix="APP", env={"APP__A": "yes"})
    assert cfg == {"a": True}


def test_bool_coercion_no():
    cfg = load({"a": True}, prefix="APP", env={"APP__A": "no"})
    assert cfg == {"a": False}


